fails = []


def check(ok, what):
    print(("ok   " if ok else "FAIL ") + what)
    if not ok:
        fails.append(what)


# --- a shader's passes and channels, read --------------------------------------------------------------
one = "void mainImage(out vec4 c, in vec2 p) { c = vec4(1.0); }"
ps = vj_glsl.passes(one)
check(len(ps) == 1 and ps[0][0] == "image" and [ps[0][2][k] for k in range(4)] == list(vj_glsl.DEFAULT_CHANNELS),
      "one pass: the image, the channels the defaults")
multi = """//@ iChannel3 = picture
//@ common
float half_(float x) { return x * 0.5; }
//@ buffer B
//@ iChannel0 = B
void mainImage(out vec4 c, in vec2 p) { c = texture(iChannel0, p / iResolution.xy) + vec4(half_(0.2), 0.0, 0.0, 0.0); }
//@ buffer A
void mainImage(out vec4 c, in vec2 p) { c = vec4(0.0, 0.25, 0.0, 1.0); }
//@ image
//@ iChannel0 = A
//@ iChannel1 = B
void mainImage(out vec4 c, in vec2 p) { vec2 uv = p / iResolution.xy;
    c = vec4(texture(iChannel1, uv).r, texture(iChannel0, uv).g, texture(iChannel3, uv).b, 1.0); }
"""
ps = vj_glsl.passes(multi)
check([p[0] for p in ps] == ["A", "B", "image"], "passes in Shadertoy's order: A, B, then the image")
check(ps[1][2][0] == "B" and ps[2][2][0] == "A" and ps[2][2][1] == "B" and ps[2][2][3] == "picture" and
      ps[0][2][2] == "noise", "each pass its channels: its own, those before the passes, the defaults")
check(all("half_" in p[1] for p in ps), "Common before every pass")
check(vj_glsl.channels_of(multi) == ["A", "B", "noise", "picture"], "the image's channels for the deck's row")
for bad, what in (("//@ iChannel0 = banana\n" + one, "a channel that is none"),
                  ("//@ buffer A\n" + one, "passes and no image")):
    try:
        vj_glsl.passes(bad)
        check(False, what + ": said")
    except ValueError as e:
        check(True, f"{what}: said ({e})")

# --- MilkDrop 2's shaders, translated ----------------------------------------------------------------
hlsl = """float3 tint = 0.5;
sampler sampler_pw_noise_lq;
static const float k = 2;
shader_body
{
    float2 d = uv - 0.5;
    ret = 0;
    ret = lerp(GetPixel(uv), GetBlur2(uv), saturate(length(d) * k));
    ret *= tint * frac(time) + tex3D(sampler_noisevol_hq, float3(uv, time)).x;
}"""
src = milk_md2.translate(hlsl, "comp")
check("tint = vec3(0.5);" in src and "ret = vec3(0.0);" in src and "const float k = 2.0;" in src and
      "sampler sampler_pw" not in src, "HLSL's ways made GLSL's: a number for a vector, static const, samplers")

# the typed translation: what HLSL converts by itself, written out
from native import hlsl as H                                   # noqa: E402


def body(code, head=""):
    return milk_md2.translate(head + "\nshader_body {\n" + code + "\n}", "comp").split(milk_md2.MARK, 1)[1]


cases = [
    ("float x = tex2D(sampler_main, uv);", "float x = (texture(sampler_main, uv)).x;", "a vector cut to a number"),
    ("ret = tex2D(sampler_main, uv);", "ret = (texture(sampler_main, uv)).xyz;", "a float4 cut to ret's float3"),
    ("float3 c = 1; c = pow(c, 2);", "pow(c, vec3(2.0))", "pow's number made the vector's size"),
    ("float2 a = uv * aspect;", "(uv * (aspect).xy)", "two sizes in a sum: the larger cut"),
    ("int n = 3; float f = 6.28 * n / 5;", "float(n)", "an int where a float goes"),
    ("float t = time; ret = t.xxx;", "ret = vec3(t);", "a number swizzled"),
    ("float m = time % 2;", "_hlsl_fmod(time, 2.0)", "% on floats"),
    ("float x = time; if (x) ret = 1;", "if ((x != 0.0))", "a number as a condition"),
    ("float2 v = mul(uv, float2x2(1, 0, 0, 1));", "(mat2(1, 0, 0, 1) * uv)", "mul(v, M): HLSL's rows, GLSL's columns"),
    ("float3 texture = 1; float input = 2; float a__b = 3;", "h_texture", "names GLSL keeps for itself renamed"),
    ("q5 = q5 * 2; ret = q5;", "h_w_q5 = q5;", "an input written to: a copy of it"),
    ("ret = sat(GetPixel(uv).x);", "_hlsl_saturate", "a #define in the head used in the body"),
    ("float lum = lum(GetPixel(uv)); ret = lum;", "h_lum = lum(", "a variable named like a helper"),
    ("ret = rot_d2[1];", "rot_d2[1]", "MilkDrop's turning matrices"),
    ("ret = tex2D(sampler_lichen, uv).xyz;", "uniform sampler2D sampler_lichen;", "a texture of the preset's own, undeclared"),
]
for code, want, what in cases:
    try:
        got = body(code, "#define sat saturate\n")
    except Exception as e:
        got = f"{type(e).__name__}: {e}"
    ok_ = want in got or want in milk_md2.translate("#define sat saturate\nshader_body {\n" + code + "\n}", "comp")
    check(ok_, f"typed: {what}" + ("" if ok_ else f"\n{got}"))
flat = H.translate("static const float4 s[2] = { 1, 2, 3, 4, 5, 6, 7, 8 };", "ret = s[1].xyz;", milk_md2._symbols(),
                   milk_md2._HELPERS)[0]
check("vec4[2](vec4(1.0, 2.0, 3.0, 4.0), vec4(5.0, 6.0, 7.0, 8.0))" in flat, "an array of vectors given number by number")
state = H.translate("sampler sampler_grad = sampler_state { AddressU = WRAP; AddressV = WRAP; };", "ret = 0;",
                    milk_md2._symbols(), milk_md2._HELPERS)
check(("sampler_grad", ("sampler2D", 0)) in state[1], "a sampler_state block passed over")
try:
    milk_md2.translate("float3 x = 1;", "warp")
    check(False, "no shader_body: said")
except ValueError:
    check(True, "no shader_body: said")
fb = np.zeros((8, 8, 3), np.float32)
check(milk_md2.blurs(fb, src)[1] is not fb and milk_md2.blurs(fb, milk_md2.translate("shader_body { ret = 1; }", "comp"))[0] is fb,
      "the blurs made only for a shader that reads one")

# --- a preset with shapes and a custom wave ----------------------------------------------------------
PRESET = """[preset00]
fDecay=0.9
fWaveAlpha=0
shapecode_0_enabled=1
shapecode_0_sides=4
shapecode_0_num_inst=2
shapecode_0_rad=0.2
shapecode_0_r=1
shapecode_0_g=0
shapecode_0_b=0
shapecode_0_a=1
shapecode_0_r2=1
shapecode_0_g2=0
shapecode_0_b2=0
shapecode_0_a2=1
shapecode_0_border_a=0
shape_0_init1=t1 = 0.3;
shape_0_per_frame1=x = 0.5 + if(equal(instance, 0), -t1, t1); y = 0.5;
shapecode_1_enabled=0
wavecode_0_enabled=1
wavecode_0_samples=64
wavecode_0_bUseDots=1
wavecode_0_r=0
wavecode_0_g=0
wavecode_0_b=1
wave_0_per_point1=x = sample; y = 0.9;
"""
pre = milk.parse(PRESET, "shapes")
check(len(pre["shapes"]) == 1 and len(pre["waves"]) == 1 and pre["shapes"][0]["p"]["num_inst"] == 2,
      "enabled shapes and waves read, a disabled one left out")


class C:
    pass


def ctx(w=64, h=48):
    c = C()
    c.w, c.h = w, h
    c.u, c.v = np.meshgrid(np.linspace(0, 1, w, dtype=np.float32), np.linspace(0, 1, h, dtype=np.float32))
    c.x, c.y = (c.u - 0.5) * 2 * w / h, (c.v - 0.5) * 2
    c.r, c.a = np.hypot(c.x, c.y), np.arctan2(c.y, c.x)
    c.amount, c.speed, c.video, c.bands = 0.5, 1.0, None, None
    c.t, c.dt, c.beat, c.bass, c.mid, c.treb, c.level = 0.0, 1 / 30, 0.0, 0.3, 0.3, 0.3, 0.5
    c.wave = np.zeros(64, np.float32)
    return c


c = ctx()
st = {}
out = milk.look_draw(pre)(c, st)
left, right = out[24, int(0.2 * 63)], out[24, int(0.8 * 63)]
check(left[0] > 0.9 and right[0] > 0.9 and out[24, 32, 0] < 0.2, f"two instances of a red square, either side ({left}, {right})")
check(out[int(0.1 * 47), 10, 2] > 0.5, "the custom wave's blue dots along the top")

# --- run on the graphics card ---------------------------------------------------------------------------
# --- Shadertoy: WebGL's GLSL where the desktop's differs, its JSON imported -----------------------------------------
w = vj_glsl._webgl("float noise2(vec2 p) { return 0.; }\n#define f(a) (a * 2.)\n#define tri(a, g) g(a, a)\n"
                   "#define Fa(a, b) (a + b)\nfloat m() { float f = f(1.); return tri(f, Fa); }")
check("vj_noise2" in w and "#define vjm_f(a)" in w and "float f = vjm_f(1.)" in w and "#define Fa(a, b)" in w
      and "tri(f, Fa)" in w and w.count("\n") == 4,
      "WebGL's ways: noise2 renamed, a macro named like a variable renamed, one passed bare kept, lines kept")
TOY = {"Shader": {"info": {"id": "abcDEF", "name": "Two Pass Test", "username": "someone", "description": "a test"},
                  "renderpass": [
    {"type": "common", "name": "Common", "inputs": [], "outputs": [], "code": "float k() { return 0.5; }"},
    {"type": "buffer", "name": "Buffer A", "outputs": [{"id": 257, "channel": 0}],
     "inputs": [{"id": 257, "ctype": "buffer", "channel": 0}, {"id": 33, "ctype": "keyboard", "channel": 1}],
     "code": "void mainImage(out vec4 o, in vec2 u) { o = texture(iChannel0, u / iResolution.xy) * 0.9 + k() * 0.1; }"},
    {"type": "image", "name": "Image", "outputs": [{"id": 37, "channel": 0}],
     "inputs": [{"id": 257, "ctype": "buffer", "channel": 0},
                {"id": 9, "ctype": "cubemap", "channel": 1, "src": "/media/a/cube.png"},
                {"id": 7, "ctype": "texture", "channel": 2,
                 "src": "/media/a/08b42b43ae9d3c0605da11d0eac86618ea888e62cdd9518ee8b9097488b31560.png"}],
     "code": "void mainImage(out vec4 o, in vec2 u) { vec2 p = u / iResolution.xy;\n"
             "  o = texture(iChannel0, p) + texture(iChannel1, vec3(p - 0.5, 1.)) * 0.5"
             " + texture(iChannel2, (vec2(65 % 16, 15 - 65 / 16) + p) / 16.) * 0.0 + iChannelTime[0] * 0. + iSampleRate * 0.; }"},
    {"type": "sound", "name": "Sound", "inputs": [], "outputs": [], "code": "vec2 mainSound(int s, float t) { return vec2(0); }"}]}}
src, nm, lost = vj_glsl.from_shadertoy(TOY)
plan = vj_glsl.passes(src)
check(nm == "Two Pass Test" and "shadertoy.com/view/abcDEF" in src and [p[0] for p in plan] == ["A", "image"]
      and plan[0][2][0] == "A" and plan[1][2] == {0: "A", 1: "cube", 2: "font", 3: "none"} and "float k()" in plan[1][1],
      f"a Shadertoy JSON: its passes, its inputs as channels, Common in each, its page kept ({plan and plan[1][2]})")
check(any("keyboard" in x for x in lost) and any("Sound" in x for x in lost), f"what is not here, said ({lost})")
d = tempfile.mkdtemp()


class _Proj:
    path = d


jp = os.path.join(d, "toy.json")
json.dump(TOY, open(jp, "w"))
got = vj_looks.import_file(_Proj(), jp)
check(got.endswith("two_pass_test.glsl") and os.path.exists(got) and "//@ buffer A" in open(got).read(),
      "Import... takes a Shadertoy .json: written to looks/ as a .glsl named after it")
a = vj_glsl.font_atlas(16)
check(a.shape == (256, 256, 4) and a[::-1][4 * 16:5 * 16, 1 * 16:2 * 16, 0].max() > 200 and a[::-1][:32, :, 0].max() == 0,
      "the font atlas: 'A' in its cell (row 4, column 1), nothing in the control codes' rows")

ok, why = vj_glsl.available()
if ok:
    uni = {"iResolution": (16.0, 12.0, 1.0), "iTime": 0.0}
    pic = os.path.join(tempfile.mkdtemp(), "p.png")
    from PIL import Image
    Image.new("RGB", (4, 4), (0, 0, 255)).save(pic)
    for _ in range(3):
        img, err = vj_glsl.render("multi", multi, 16, 12, uni, None, None, wait=True, picture=pic)
    check(not err and abs(img[6, 8, 0] - 0.3) < 0.02 and abs(img[6, 8, 1] - 0.25) < 0.02 and img[6, 8, 2] > 0.95,
          f"passes run: B adds a tenth a frame (three: 0.3), A's green, the picture's blue ({err} {img[6, 8] if img is not None else None})")
    img, err = vj_glsl.render("multi2", multi, 16, 12, uni, None, None, wait=True, picture=pic, channels=["", "", "", "none"])
    check(img is not None and img[6, 8, 2] < 0.05, "a deck's choice over the file's: iChannel3 nothing")
    MD2 = PRESET.replace("fWaveAlpha=0", "fWaveAlpha=0\nwarp_1=`shader_body\nwarp_2=`{ ret = tex2D(sampler_main, uv).xyz * 0.5; }\n"
                         "comp_1=`shader_body\ncomp_2=`{ ret = float3(0, 1, 0) * (1 - GetPixel(uv).x); }")
    pre2 = milk.parse(MD2, "md2")
    st2 = {}
    out2 = milk.look_draw(pre2)(ctx(), st2)
    check(not st2.get("warn") and out2[24, 32, 1] > 0.9 and out2[24, int(0.2 * 63), 1] < 0.1,
          f"MilkDrop 2's composite shader shows the frame its way (green where there is no square) {st2.get('warn')}")
    bad = PRESET + "comp_1=`shader_body\ncomp_2=`{ ret = nope; }\n"
    st3 = {}
    out3 = milk.look_draw(milk.parse(bad, "bad"))(ctx(), st3)
    check("comp shader left out" in st3.get("warn", "") and out3[24, int(0.2 * 63), 0] > 0.9,
          "a shader that will not compile: the preset runs without it, and says so")
    # every typed case above compiles on the graphics card
    bad_ = []
    for code, want, what in cases:
        src_ = milk_md2.translate("#define sat saturate\nshader_body {\n" + code + "\n}", "comp")
        img_, err_ = milk_md2.run(src_, 16, 12, milk_md2.uniforms({}, 16, 12, 1.0, 1), np.zeros((12, 16, 3), np.float32),
                                  (np.zeros((12, 16, 3), np.float32),) * 3, None)
        if err_:
            bad_.append(f"{what}: {err_[:200]}")
    check(not bad_, "the typed translations compile" + (f": {bad_}" if bad_ else ""))
    g = vj_glsl._gl()
    noisy = milk.parse(PRESET + "comp_1=`shader_body\ncomp_2=`{ ret = GetPixel(uv) + tex2D(sampler_noise_lq, uv).xyz * 0.1; }\n",
                       "noisy")
    for _ in range(2):
        milk.look_draw(noisy)(ctx(), {})
    n = (len(g.tex), len(g.static), len(g.progs))
    for _ in range(6):                                           # six new states (six look changes): nothing more kept
        milk.look_draw(noisy)(ctx(), {})
    check((len(g.tex), len(g.static), len(g.progs)) == n and len(g.static) >= 1,
          f"MD2's textures one a name and the noise once, however many states ({n})")
    for _ in range(3):
        img, err = vj_glsl.render("toy-import", src, 32, 18, {"iResolution": (32.0, 18.0, 1.0), "iTime": 1.0}, None,
                                  None, wait=True)
    check(not err and img is not None and img[9, 16].mean() > 0.1,
          f"the imported shader runs: its buffer, a cubemap channel (the sky), the font, iChannelTime ({err})")
else:
    print("skip the runs: " + why)

# --- the GL thread's jobs: one a key, the newer in the older's place --------------------------------------
jobs = vj_glsl._Jobs()
jobs.put("a", 1); jobs.put("b", 2); jobs.put("a", 3)
check([jobs.get(), jobs.get()] == [3, 2] and not jobs.jobs, "a deck's frame asked for again replaces the one waiting")


# --- a project's Python looks: run only once allowed -----------------------------------------------------
class Proj:
    path = tempfile.mkdtemp()


d = vj_looks.user_dir(Proj)
os.makedirs(d, exist_ok=True)
open(os.path.join(d, "mine.py"), "w").write("NAME = 'Mine Test'\ndef draw(c, st):\n    return c.u[..., None].repeat(3, 2)\n")
errs = vj_looks.load_user(Proj, allow_py=False)
check("Mine Test" not in vj_looks.LOOKS and errs == [("mine.py", vj_looks.NOT_ALLOWED)], "not allowed: not run, said")
errs = vj_looks.load_user(Proj, allow_py=True)
check("Mine Test" in vj_looks.LOOKS and not errs, "allowed: run and listed")
errs = vj_looks.load_user(Proj, allow_py=False)
check("Mine Test" not in vj_looks.LOOKS, "no longer allowed: unlisted")
os.remove(os.path.join(d, "mine.py"))
vj_looks.load_user(Proj)

